from __future__ import annotations

from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected exactly one anchor, found {count}: {old[:120]!r}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


# SpeechWorkerClient: carry compare authority only when explicitly configured.
replace_once(
    "linux/backend/app/ai/speech/client.py",
    '''    def open_session(\n        self,\n        session_id: str,\n        sample_rate: int = 16000,\n        *,\n        speaker_backend: str | None = None,\n    ) -> dict[str, Any]:\n        explicit_backend = speaker_backend is not None\n        backend_key = str(speaker_backend or "xvector").strip().lower()\n        if not backend_key:\n            raise ValueError("speaker_backend must not be empty")\n        result = self._require_dict(\n            self._request(\n                "open_session",\n                session_id=session_id,\n                sample_rate=int(sample_rate),\n                speaker_backend=backend_key,\n            )\n        )\n        if not explicit_backend:\n            result.pop("speaker_backend", None)\n        return result\n''',
    '''    def open_session(\n        self,\n        session_id: str,\n        sample_rate: int = 16000,\n        *,\n        speaker_backend: str | None = None,\n        authoritative_backend: str | None = None,\n    ) -> dict[str, Any]:\n        explicit_backend = speaker_backend is not None\n        backend_key = str(speaker_backend or "xvector").strip().lower()\n        if not backend_key:\n            raise ValueError("speaker_backend must not be empty")\n        authority_key = (\n            None\n            if authoritative_backend is None\n            else str(authoritative_backend).strip().lower()\n        )\n        concrete = {"xvector", "eres2net_large"}\n        if backend_key == "compare":\n            if authority_key not in concrete:\n                raise ValueError("authoritative_backend is required for compare mode")\n        elif authority_key is not None and authority_key != backend_key:\n            raise ValueError("authoritative_backend must match the single speaker backend")\n\n        payload: dict[str, Any] = {\n            "session_id": session_id,\n            "sample_rate": int(sample_rate),\n            "speaker_backend": backend_key,\n        }\n        if authority_key is not None:\n            payload["authoritative_backend"] = authority_key\n        result = self._require_dict(self._request("open_session", **payload))\n        if not explicit_backend:\n            result.pop("speaker_backend", None)\n            result.pop("authoritative_backend", None)\n        return result\n''',
)

# AISupervisor: preserve omitted-XVector compatibility while forwarding compare authority.
replace_once(
    "linux/backend/app/ai/supervisor.py",
    '''    def open_speech_session(\n        self,\n        session_id: str,\n        *,\n        sample_rate: int = 16000,\n        speaker_backend: str | None = None,\n    ) -> dict[str, Any]:\n        explicit_backend = speaker_backend is not None\n        if explicit_backend:\n            result = self._speech_client.open_session(\n                session_id,\n                sample_rate=sample_rate,\n                speaker_backend=speaker_backend,\n            )\n        else:\n            result = self._speech_client.open_session(\n                session_id,\n                sample_rate=sample_rate,\n            )\n            # In-process mock historically returned no backend discriminator.\n            # Normalize the omitted-backend call even if an internal client adds it.\n            result = dict(result)\n            result.pop("speaker_backend", None)\n        self._speech_sessions.add(session_id)\n        return result\n''',
    '''    def open_speech_session(\n        self,\n        session_id: str,\n        *,\n        sample_rate: int = 16000,\n        speaker_backend: str | None = None,\n        authoritative_backend: str | None = None,\n    ) -> dict[str, Any]:\n        explicit_backend = speaker_backend is not None\n        if explicit_backend:\n            kwargs: dict[str, Any] = {\n                "sample_rate": sample_rate,\n                "speaker_backend": speaker_backend,\n            }\n            if authoritative_backend is not None:\n                kwargs["authoritative_backend"] = authoritative_backend\n            result = self._speech_client.open_session(session_id, **kwargs)\n        else:\n            if authoritative_backend is not None:\n                raise ValueError("authoritative_backend requires an explicit speaker_backend")\n            result = self._speech_client.open_session(\n                session_id,\n                sample_rate=sample_rate,\n            )\n            # In-process mock historically returned no backend discriminator.\n            # Normalize the omitted-backend call even if an internal client adds it.\n            result = dict(result)\n            result.pop("speaker_backend", None)\n            result.pop("authoritative_backend", None)\n        self._speech_sessions.add(session_id)\n        return result\n''',
)

# In-process mock accepts the same session-selection contract as the real worker.
replace_once(
    "linux/backend/app/ai/supervisor.py",
    '''    def open_session(\n        self,\n        session_id: str,\n        sample_rate: int = 16000,\n        speaker_backend: str = "xvector",\n    ) -> dict[str, Any]:\n        session_id = str(session_id).strip()\n        sample_rate = int(sample_rate)\n        speaker_backend = str(speaker_backend or "xvector").strip().lower()\n        if not session_id:\n            raise AIError("session_id is required")\n        if sample_rate <= 0:\n            raise AIError("sample_rate must be positive")\n        if speaker_backend not in {"xvector", "eres2net_large"}:\n            raise AIError("unsupported speaker backend", details={"speaker_backend": speaker_backend})\n        with self._lock:\n            self._sessions[session_id] = {\n                "sample_rate": sample_rate,\n                "bytes_received": 0,\n                "speaker_backend": speaker_backend,\n            }\n        return {\n            "session_id": session_id,\n            "sample_rate": sample_rate,\n            "speaker_backend": speaker_backend,\n        }\n''',
    '''    def open_session(\n        self,\n        session_id: str,\n        sample_rate: int = 16000,\n        speaker_backend: str = "xvector",\n        authoritative_backend: str | None = None,\n    ) -> dict[str, Any]:\n        session_id = str(session_id).strip()\n        sample_rate = int(sample_rate)\n        speaker_backend = str(speaker_backend or "xvector").strip().lower()\n        authority_key = (\n            None\n            if authoritative_backend is None\n            else str(authoritative_backend).strip().lower()\n        )\n        concrete = {"xvector", "eres2net_large"}\n        if not session_id:\n            raise AIError("session_id is required")\n        if sample_rate <= 0:\n            raise AIError("sample_rate must be positive")\n        if speaker_backend not in {*concrete, "compare"}:\n            raise AIError("unsupported speaker backend", details={"speaker_backend": speaker_backend})\n        if speaker_backend == "compare":\n            if authority_key not in concrete:\n                raise AIError("authoritative speaker backend is required in compare mode")\n        elif authority_key is not None and authority_key != speaker_backend:\n            raise AIError("authoritative speaker backend must match single backend")\n        with self._lock:\n            self._sessions[session_id] = {\n                "sample_rate": sample_rate,\n                "bytes_received": 0,\n                "speaker_backend": speaker_backend,\n                "authoritative_backend": authority_key or speaker_backend,\n            }\n        result = {\n            "session_id": session_id,\n            "sample_rate": sample_rate,\n            "speaker_backend": speaker_backend,\n        }\n        if authority_key is not None:\n            result["authoritative_backend"] = authority_key\n        return result\n''',
)

